import os
import sys
import platform


LICENSES_FORMAT = 'csv'
LICENSES_FILE = 'LICENSES'
VERSION_FILE = '../__version__.txt'


def parse_requirements(file_name):
    python_version = platform.python_version()
    sys_platform = sys.platform

    def condition_applies(line):
        if ';' in line:
            req, condition = line.split(';', 1)
            condition = condition.strip()
            if condition == '':
                return True

            # Build safe condition, replace 'python_version' and 'sys_platform'
            condition = condition.replace('python_version', f"'{python_version}'").replace('sys_platform', f"'{sys_platform}'")
            return eval(condition)
        return True

    with open(file_name, 'r') as f:
        return [
            line.split(';')[0].strip() for line in f
            if line.strip() and not (line.startswith("#") or line.startswith("-")) and condition_applies(line)
        ]


def get_version():
    try:
        current_dir = os.path.dirname(os.path.abspath(__file__))
        parent_dir = os.path.join(current_dir, '..')
        with open(f"{parent_dir}/{VERSION_FILE}") as f:
            return f.read().strip()
    except FileNotFoundError as e:
        with open(VERSION_FILE, 'w') as f:
            f.write('0.0.0')
